// Language Context - provides i18n support for the app
import { createContext, useContext, useState, useEffect, ReactNode } from 'react';

type Language = 'th' | 'en' | 'ko' | 'zh';

interface LanguageContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
  t: (key: string) => string;
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>(() => {
    const saved = localStorage.getItem('app-language');
    return (saved as Language) || 'th';
  });

  const setLanguage = (lang: Language) => {
    setLanguageState(lang);
    localStorage.setItem('app-language', lang);
  };

  const t = (key: string): string => {
    const translations = language === 'th' ? thTranslations : language === 'ko' ? koTranslations : language === 'zh' ? zhTranslations : enTranslations;
    return translations[key] || key;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t }}>
      {children}
    </LanguageContext.Provider>
  );
}

let warnedMissingProvider = false;

export function useLanguage() {
  const context = useContext(LanguageContext);

  // Safety fallback to prevent blank-screen crashes if the provider isn't mounted
  // (e.g. during cached/stale builds or misconfigured trees).
  if (!context) {
    if (!warnedMissingProvider) {
      warnedMissingProvider = true;
      console.warn("useLanguage used without LanguageProvider; falling back to defaults");
    }

    return {
      language: "en" as Language,
      setLanguage: () => {},
      t: (key: string) => key,
    } satisfies LanguageContextType;
  }

  return context;
}

